def compute(vars):
    income_tax = vars["Income Tax"]
    tax_rate = vars["Tax Rate"]

    normalized_tax_rate = tax_rate / 100.0

    if normalized_tax_rate == 0:
        return None

    taxable_income = income_tax / normalized_tax_rate

    return {
        "value": taxable_income,
        "trace": {
            "Income Tax": income_tax,
            "Tax Rate": tax_rate,
            "normalized_tax_rate": normalized_tax_rate,
            "output_meta": {
                "currency": "$",
                "scale": "thousands",
                "unit": None
            }
        }
    }
